class Line:
    sku: str
    qty: int
    unit_cents: int

def line_amount(l: Line) -> int:
    a = l.qty * l.unit_cents
    if l.qty >= 10:
        return a - a // 10
    return a

def apply_coupon(sub: int, coupon: str) -> Result[int, str]:
    if coupon == "":
        return Ok(sub)
    if coupon == "SAVE500":
        return Ok(max(sub - 500, 1))
    if coupon == "PCT10":
        return Ok(sub - sub // 10)
    if coupon == "BIG20":
        if sub < 10000:
            return Err("coupon not applicable: BIG20")
        return Ok(sub - sub // 5)
    return Err("unknown coupon: " + coupon)

def invoice_total(lines: list[Line], coupon: str) -> Result[int, str]:
    for l in lines:
        if l.qty < 1:
            return Err("bad quantity: " + l.sku)
    sub = sum(map(lines, lambda l: line_amount(l)))
    amount = apply_coupon(sub, coupon)?
    tax = (amount * 8 + 50) // 100
    return Ok(amount + tax)

