def max_subarray(xs: list[int]) -> Option[tuple[int, int, int]]:
    if len(xs) == 0:
        return None
    best = (unwrap_or(first(xs), 0), 0, 0)
    for p in enumerate(xs):
        s = 0
        for q in enumerate(drop(xs, p[0])):
            s += q[1]
            if s > best[0]:
                best = (s, p[0], p[0] + q[0])
    return Some(best)

