        return False
    if len(groups) == 1:
        return True
    g0 = str_len(unwrap_or(first(groups), ""))
    if g0 < 1 or g0 > 3:
        return False
    for g in drop(groups, 1):
        if str_len(g) != 3:
            return False
    return True

def parse_money(s: str) -> Result[int, str]:
