        after = join(drop(pieces, 1), ".")
        ccs = split(after, "")
        if len(ccs) != 2 or not all_digits(ccs):
            return Err("bad cents")
        cents = unwrap_or(parse_int(after), 0)
    if not dollars_ok(dollars):
        return Err("bad dollars")
    total = unwrap_or(parse_int(join(split(dollars, ","), "")), 0) * 100 + cents
    if neg:
        return Ok(0 - total)
    return Ok(total)

