    cur: int
    history: list[tuple[str, int]]

def step(e: Editor, op: EditOp) -> Editor:
    cs = split(e.text, "")
    saved = append(e.history, (e.text, e.cur))
    match op:
        case Insert(t):
            return insert(e, t, saved)
        case Delete(n):
            return delete(e, min(n, e.cur), saved)
        case Left(n):
            return Editor(text=e.text, cur=max(0, e.cur - n), history=e.history)
        case Right(n):
            return Editor(text=e.text, cur=min(len(cs), e.cur + n), history=e.history)
        case Undo:
            return undo(e)

def insert(e: Editor, t: str, saved: list[tuple[str, int]]) -> Editor:
    cs = split(e.text, "")
    text = join(take(cs, e.cur), "") + t + join(drop(cs, e.cur), "")
    return Editor(text=text, cur=e.cur + str_len(t), history=saved)

def delete(e: Editor, k: int, saved: list[tuple[str, int]]) -> Editor:
    cs = split(e.text, "")
    text = join(take(cs, e.cur - k), "") + join(drop(cs, e.cur), "")
    return Editor(text=text, cur=max(0, e.cur - k), history=saved)

def undo(e: Editor) -> Editor:
    n = len(e.history)
    match last(e.history):
        case Some(p):
            return Editor(text=p[0], cur=p[1], history=take(e.history, n - 1))
        case None:
            return e

def text_editor(ops: list[EditOp]) -> str:
    start = Editor(text="", cur=0, history=[])
    return fold(ops, start, lambda e, op: step(e, op)).text

