def mark(cells: list[str], i: int) -> str:
    return unwrap_or(first(drop(cells, i)), "")

def has_line(cells: list[str], p: str) -> bool:
    rows = [[0, 1, 2], [3, 4, 5], [6, 7, 8]]
    cols_diags = [[0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]
    lines = fold(cols_diags, rows, lambda acc, l: append(acc, l))
    full = filter(lines, lambda l: len(filter(l, lambda i: mark(cells, i) == p)) == 3)
    return len(full) > 0

def tic_tac_toe(board: list[str]) -> str:
    cells = split(join(board, ""), "")
    nx = len(filter(cells, lambda c: c == "X"))
    no = len(filter(cells, lambda c: c == "O"))
    xw = has_line(cells, "X")
    ow = has_line(cells, "O")
    if nx != no and nx != no + 1:
        return "invalid"
    if xw and ow:
        return "invalid"
    if xw and nx != no + 1:
        return "invalid"
    if ow and nx != no:
        return "invalid"
    if xw:
        return "X wins"
    if ow:
        return "O wins"
    if nx + no == 9:
        return "draw"
    return "in progress"

